const photos=['data:image/jpeg;base64,', 'https://images.unsplash.com/photo-1464305795204-6f5bbfc7fb81?auto=format&fit=crop&w=700&q=85', 'data:image/jpeg;base64,', 'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=700&q=85'];const data=[['Bolo trufado de chocolate','Bolos','Massa de chocolate e recheio cremoso',90],['Torta de morango','Tortas','Base crocante, creme e morangos',85],['Taça da felicidade','Sobremesas','Camadas de bolo, creme e frutas',45],['Box de brownies','Outros','Caixa com quatro brownies',35]];const cats=['Bolos festivos','Tortas especiais','Sobremesas artesanais','Kits e outros'];const $=id=>document.getElementById(id);const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});let filter='Todos',cart={};function setFilter(v){filter=v;render()}if($('categories'))$('categories').innerHTML=cats.map((c,i)=>`<a class="category" href="#catalogo" data-filter="${data[i][1]}"><img src="${photos[i]}" alt="Imagem ilustrativa" loading="lazy"><span><b>${c}</b><br>Explorar →</span></a>`).join('');function render(){$('filters').innerHTML=['Todos','Bolos','Tortas','Sobremesas','Outros'].map(c=>`<button class="${filter===c?'selected':''}" data-filter="${c}" aria-pressed="${filter===c}">${c}</button>`).join('');const q=$('search').value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');$('products').innerHTML=data.map((d,i)=>({d,i})).filter(({d})=>(filter==='Todos'||d[1]===filter)&&d.join(' ').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q)).map(({d,i})=>`<article class="product reveal"><img src="${photos[i]}" alt="${d[0]} ilustrativo" loading="lazy"><div class="copy"><span class="eyebrow">${d[1]}</span><h3>${d[0]}</h3><p>${d[2]}</p><strong>${money(d[3])} · exemplo</strong><button class="pill red" data-add="${i}">Encomendar +</button></div></article>`).join('')||'<p>Nenhum produto encontrado.</p>'}function update(){let n=0,t=0;$('lines').innerHTML=Object.entries(cart).map(([i,v])=>{n+=v;t+=v*data[i][3];return `<div class="line"><div>${data[i][0]}<br>${money(v*data[i][3])}</div><div><button data-dec="${i}" aria-label="Diminuir">−</button> ${v} <button data-inc="${i}" aria-label="Aumentar">+</button></div></div>`}).join('')||'<p>Sua encomenda está vazia.</p>';$('count').textContent=n;$('total').textContent='Total demonstrativo: '+money(t);$('order').querySelector('button').disabled=!n}function closeMenus(){document.querySelectorAll('.dropdown').forEach(d=>{d.querySelector('.submenu').hidden=true;d.querySelector('button').setAttribute('aria-expanded','false')})}document.querySelectorAll('.dropdown').forEach(d=>{const b=d.querySelector('button'),s=d.querySelector('.submenu');const open=()=>{closeMenus();s.hidden=false;b.setAttribute('aria-expanded','true')};b.onclick=()=>{const was=!s.hidden;closeMenus();if(!was)open()};d.addEventListener('mouseenter',()=>{if(matchMedia('(hover:hover) and (min-width:901px)').matches)open()});d.addEventListener('mouseleave',()=>{if(matchMedia('(hover:hover) and (min-width:901px)').matches)closeMenus()})});document.addEventListener('click',e=>{const b=e.target.closest('[data-filter],[data-add],[data-inc],[data-dec]');if(!e.target.closest('.dropdown'))closeMenus();if(b){if(b.dataset.filter){if(b.tagName==='A')$('search').value='';setFilter(b.dataset.filter);closeMenus()}else{const i=b.dataset.add??b.dataset.inc??b.dataset.dec;cart[i]=(cart[i]||0)+(b.dataset.dec!==undefined?-1:1);if(cart[i]<=0)delete cart[i];update();if(b.dataset.add!==undefined&&!$('cart').open)$('cart').showModal()}}if(e.target.closest('nav a')){$('nav').classList.remove('open');$('toggle').setAttribute('aria-expanded','false')}});$('toggle').onclick=()=>{$('toggle').setAttribute('aria-expanded',String($('nav').classList.toggle('open')))};$('searchTop').onclick=()=>{$('catalogo').scrollIntoView();$('search').focus({preventScroll:true})};$('search').oninput=render;$('cartOpen').onclick=()=>$('cart').showModal();$('close').onclick=()=>$('cart').close();$('cart').addEventListener('click',e=>{if(e.target===$('cart')){const r=$('cart').getBoundingClientRect();if(e.clientX<r.left)$('cart').close()}});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenus()});const today=new Date();$('date').min=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');$('order').onsubmit=e=>{e.preventDefault();if(!Object.keys(cart).length)return;const msg=['Olá! Gostaria de consultar uma encomenda (prévia demonstrativa).','Nome: '+$('customer').value,'Data: '+$('date').value,'Modalidade: '+$('mode').value,...Object.entries(cart).map(([i,v])=>`${v} x ${data[i][0]}`),'Podem confirmar disponibilidade e valores oficiais?'].join('\n');window.open('https://wa.me/5531991662290?text='+encodeURIComponent(msg),'_blank','noopener')};render();update();if(window.lucide)lucide.createIcons();